"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[719],{5719:(e,a,i)=>{i.d(a,{Df:()=>d,jA:()=>l});let t={kind:"pair",desktop:"fp-home.webp",mobile:"fp-home-mobile.webp",url:"fashionparadisecy.com"},r={kind:"pair",desktop:"at-store.webp",mobile:"at-store-mobile.webp",url:"adatrend.tech",mock:!0},n=[{slug:"fashion-paradise",name:"Fashion Paradise",kind:"Boutique online store",tag:"Live site",accent:"#8a2f1c",domain:"fashionparadisecy.com",thumb:"fp-home.webp",hero:{title:"Your boutique's character, on your customer's phone.",lead:"An online store built around one boutique: its collections first, quick to shop on a phone, and run day to day by the owner.",media:t},sections:[{kicker:"Discover",title:"It opens like a lookbook.",body:"Campaigns and collections greet visitors first, so the store feels like the boutique itself rather than a list of products. The owner changes them from the back office.",media:{kind:"browser",src:"fp-editorial.webp",url:"fashionparadisecy.com"}},{kicker:"Choose",title:"Finding the right size is the easy part.",body:"Filters for size and colour, a size chart on every product, favourites saved for later, and search across the catalogue — laid out for a thumb as much as a mouse.",points:["Size and colour filters","Size chart","Favourites","Search"],media:{kind:"pair",desktop:"fp-category.webp",mobile:"fp-product-mobile.webp",url:"fashionparadisecy.com/kategori"}},{kicker:"Behind the counter",title:"The owner runs the store.",body:"New arrivals, prices and stock for each size, the homepage campaigns and the collections are all managed from the boutique's own back office. Store emails go out in the boutique's name, and replies reach the owner directly. New products can also arrive as drafts from Oddkin Operator, a chat assistant we built for the store.",media:{kind:"chips",items:["Home page","Collections","Categories","Products","Stock","Drafts","Orders"]}}],cta:{title:"Want a store that feels like your boutique?",body:"We design online stores around your brand and the way you sell, and keep them running after launch.",button:"Talk about your store"}},{slug:"adatrend",name:"AdaTrend",kind:"Boutique marketplace",tag:"Live site",accent:"#165c45",domain:"adatrend.tech",thumb:"at-store.webp",hero:{title:"Independent shops. One shared shopping world.",lead:"AdaTrend brings independent boutiques into one place to shop. Each keeps its own name and character; customers browse them all together.",media:r},sections:[{kicker:"Coming together",title:"Each boutique keeps its own character.",body:"Every shop has its own page, name and style. Together they become one catalogue, where customers browse them side by side.",media:{kind:"boutiques"}},{kicker:"01 \xb7 Shoppers",title:"Browse every boutique at once.",body:"One catalogue across all the shops, each product showing where it comes from. Guest checkout, a delivery address filled from the phone's location, and Turkish or English a tap apart.",media:{kind:"browser",src:"at-product.webp",url:"adatrend.tech/products"}},{kicker:"02 \xb7 Sellers",title:"Each shop runs its own corner.",body:"Every boutique has its own page, and a dashboard for its products, sizes and stock, its orders, and its profile and location on the map.",media:{kind:"dashboard"}},{kicker:"03 \xb7 Operator",title:"The operator keeps it in order.",body:"New boutiques are approved before they appear. The team can assign or hand over who runs a shop, step into any shop's dashboard to help, and look after the shared categories.",media:{kind:"chips",items:["Boutiques","Categories","Waiting for approval","Approve","Hand over ownership"]}}],cta:{title:"Bringing independent sellers together?",body:"We design the storefront, the sellers' tools and the operator's controls as one marketplace.",button:"Talk about a marketplace"}},{slug:"oddkin-operator",name:"Oddkin Operator",kind:"Store assistant in chat",tag:"Live",accent:"#4f8f2a",thumb:null,hero:{title:"Talk to your store. Keep the day moving.",lead:"Oddkin Operator lets a shop owner handle the store's everyday changes from a chat on their phone. Nothing changes in the shop until they approve it.",media:{kind:"chat"}},sections:[{kicker:"Who decides",title:"The owner stays in charge.",body:"It suggests a description and picks a category from your own list. It never guesses the numbers — prices, sizes and stock come from you.",points:["Every change waits for your tap. Typing “yes” is not an approval.","Publishing, prices and stock each arrive as a card with buttons.","Taking a product down archives it, so it can come back."]},{kicker:"In the chat",title:"What the day asks for.",body:"It works in Telegram and is connected store by store. Its first store is Fashion Paradise.",media:{kind:"chips",items:["Add a product from a photo","Find a product","Change a price, size by size","Adjust stock","Add a category","Take a product down"]}}],note:"The product photo comes from the live Fashion Paradise store; the conversation and the store card are an illustration.",cta:{title:"Does your team repeat the same store tasks every day?",body:"We build assistants that take on routine work and leave every decision that matters with a person.",button:"Talk about an assistant"}},{slug:"talos",name:"Project Talos",kind:"Meeting-to-action agent",tag:"Concept",accent:"#c4692a",thumb:null,hero:{title:"The meeting ends. The work moves forward.",lead:"Project Talos is our concept for an agent that notices the decisions made in a meeting, proposes the actions that follow, and carries them out in your work tools once a person approves.",media:{kind:"flow"}},sections:[{kicker:"01 \xb7 In the meeting",title:"Something gets decided.",body:"Most meetings end with decisions that live only in people's memories and scattered notes. Talos listens for the moments that commit someone to something."},{kicker:"02 \xb7 After the meeting",title:"Talos proposes the follow-through.",body:"Hearing something in a meeting is not permission. Talos drafts the action, shows exactly where it came from, and waits for a person to decide.",media:{kind:"proposal"}},{kicker:"03 \xb7 Approved",title:"Then it happens, where the team can see it.",body:"Once approved, the action is carried out in the tools the team already uses, and links back to the moment it was decided.",points:["Turning decisions into tasks and follow-up emails","Showing the source of every proposal","A person approves anything consequential"]}],note:"Talos is a concept we are building toward, not a product available today.",cta:{title:"Do decisions from your meetings get lost?",body:"If following through on meetings is a problem for your team, we would like to hear how it works today.",button:"Talk about meetings and follow-up"}}],o=[{...n[0],kind:"Butik online mağaza",tag:"Canlı site",hero:{title:"Butiğinizin karakteri, m\xfcşterinizin telefonunda.",lead:"Tek bir butik i\xe7in kurulmuş online mağaza: \xf6nce koleksiyonlar, telefondan hızlı alışveriş ve g\xfcnl\xfck işleyişi sahibinin elinde.",media:t},sections:[{...n[0].sections[0],kicker:"Keşfet",title:"Bir lookbook gibi a\xe7ılır.",body:"Ziyaret\xe7ileri \xf6nce kampanyalar ve koleksiyonlar karşılar; mağaza bir \xfcr\xfcn listesi değil, butiğin kendisi gibi hissettirir. Sahibi bunları y\xf6netim panelinden değiştirir."},{...n[0].sections[1],kicker:"Se\xe7",title:"Doğru bedeni bulmak işin kolay kısmı.",body:"Beden ve renk filtreleri, her \xfcr\xfcnde beden tablosu, sonraya saklanan favoriler ve t\xfcm katalogda arama — fare kadar başparmak i\xe7in de d\xfczenlendi.",points:["Beden ve renk filtreleri","Beden tablosu","Favoriler","Arama"]},{kicker:"Tezg\xe2hın arkası",title:"Mağazayı sahibi y\xf6netir.",body:"Yeni gelenler, fiyatlar ve beden beden stok, ana sayfa kampanyaları ve koleksiyonlar butiğin kendi y\xf6netim panelinden y\xf6netilir. Mağaza e-postaları butiğin adıyla gider, yanıtlar doğrudan sahibine ulaşır. Yeni \xfcr\xfcnler, mağaza i\xe7in geliştirdiğimiz sohbet asistanı Oddkin Operator'dan taslak olarak da gelebilir.",media:{kind:"chips",items:["Ana sayfa","Koleksiyonlar","Kategoriler","\xdcr\xfcnler","Stok","Taslaklar","Siparişler"]}}],cta:{title:"Butiğiniz gibi hissettiren bir mağaza mı istiyorsunuz?",body:"Online mağazaları markanıza ve satış şeklinize g\xf6re tasarlıyor, yayından sonra da \xe7alışır tutuyoruz.",button:"Mağazanızı konuşalım"}},{...n[1],kind:"Butik pazar yeri",tag:"Canlı site",hero:{title:"Bağımsız butikler. Ortak bir alışveriş d\xfcnyası.",lead:"AdaTrend bağımsız butikleri tek bir alışveriş yerinde buluşturur. Her biri kendi adını ve karakterini korur; m\xfcşteriler hepsini birlikte gezer.",media:r},sections:[{...n[1].sections[0],kicker:"Bir araya geliş",title:"Her butik kendi karakterini korur.",body:"Her mağazanın kendi sayfası, adı ve tarzı var. Birlikte tek bir katalog olurlar; m\xfcşteriler onları yan yana gezer."},{...n[1].sections[1],kicker:"01 \xb7 M\xfcşteriler",title:"T\xfcm butikleri aynı anda gezin.",body:"B\xfct\xfcn mağazalar tek bir katalogda; her \xfcr\xfcn nereden geldiğini g\xf6sterir. \xdcye olmadan sipariş, telefonun konumundan doldurulan teslimat adresi ve bir dokunuşla T\xfcrk\xe7e ya da İngilizce."},{...n[1].sections[2],kicker:"02 \xb7 Satıcılar",title:"Her butik kendi k\xf6şesini y\xf6netir.",body:"Her butiğin kendi sayfası ve \xfcr\xfcnleri, bedenleri ve stoğu, siparişleri, profili ve haritadaki konumu i\xe7in bir paneli vardır."},{kicker:"03 \xb7 Platform ekibi",title:"D\xfczeni platform ekibi korur.",body:"Yeni butikler g\xf6r\xfcnmeden \xf6nce onaylanır. Ekip bir mağazayı kimin y\xf6neteceğini atayabilir ya da devredebilir, yardım i\xe7in herhangi bir butiğin paneline ge\xe7ebilir ve ortak kategorileri d\xfczenler.",media:{kind:"chips",items:["Butikler","Kategoriler","Onay bekliyor","Onayla","Sahibi devret"]}}],cta:{title:"Bağımsız satıcıları bir araya mı getiriyorsunuz?",body:"Vitrini, satıcı ara\xe7larını ve platform y\xf6netimini tek bir pazar yeri olarak tasarlıyoruz.",button:"Bir pazar yerini konuşalım"}},{...n[2],kind:"Sohbette mağaza asistanı",tag:"Canlı",hero:{title:"Mağazanızla konuşun. G\xfcn aksamasın.",lead:"Oddkin Operator, mağaza sahibinin g\xfcnl\xfck değişiklikleri telefonundaki bir sohbetten yapmasını sağlar. Sahibi onaylamadan mağazada hi\xe7bir şey değişmez.",media:{kind:"chat"}},sections:[{kicker:"Kim karar verir",title:"Kontrol mağaza sahibinde.",body:"Bir a\xe7ıklama \xf6nerir ve kendi listenizden bir kategori se\xe7er. Rakamları asla tahmin etmez — fiyat, beden ve stok sizden gelir.",points:["Her değişiklik sizin dokunuşunuzu bekler. “Evet” yazmak onay sayılmaz.","Yayın, fiyat ve stok değişiklikleri d\xfcğmeli bir kartla gelir.","Kaldırılan \xfcr\xfcn silinmez, arşivlenir; yeniden geri gelebilir."]},{kicker:"Sohbette",title:"G\xfcn\xfcn istedikleri.",body:"Telegram \xfczerinden \xe7alışır ve her mağazaya ayrı bağlanır. İlk mağazası Fashion Paradise.",media:{kind:"chips",items:["Fotoğraftan \xfcr\xfcn ekleme","\xdcr\xfcn bulma","Beden beden fiyat değiştirme","Stok g\xfcncelleme","Kategori ekleme","\xdcr\xfcn\xfc yayından kaldırma"]}}],note:"\xdcr\xfcn fotoğrafı canlı Fashion Paradise mağazasından alındı; sohbet ve mağaza kartı temsil\xeedir.",cta:{title:"Ekibiniz her g\xfcn aynı mağaza işlerini mi tekrarlıyor?",body:"Rutin işi \xfcstlenen, \xf6nemli her kararı bir kişiye bırakan asistanlar geliştiriyoruz.",button:"Bir asistanı konuşalım"}},{...n[3],kind:"Toplantıdan işe ajan",tag:"Konsept",hero:{title:"Toplantı biter. İş ilerler.",lead:"Project Talos, bir toplantıda alınan kararları fark eden, ardından gelecek işleri \xf6neren ve bir kişi onayladığında bunları iş ara\xe7larınızda y\xfcr\xfcten bir ajan konseptimiz.",media:{kind:"flow"}},sections:[{...n[3].sections[0],kicker:"01 \xb7 Toplantıda",title:"Bir karar alınır.",body:"\xc7oğu toplantı, yalnızca insanların hafızasında ve dağınık notlarda yaşayan kararlarla biter. Talos, birinin bir şeyi \xfcstlendiği anlara kulak verir."},{...n[3].sections[1],kicker:"02 \xb7 Toplantıdan sonra",title:"Talos devamını \xf6nerir.",body:"Toplantıda bir şeyin s\xf6ylenmesi izin anlamına gelmez. Talos işi taslak olarak hazırlar, tam olarak nereden geldiğini g\xf6sterir ve bir kişinin karar vermesini bekler."},{kicker:"03 \xb7 Onaylandı",title:"Sonra ger\xe7ekleşir; ekibin g\xf6rebileceği yerde.",body:"Onaylandığında iş, ekibin zaten kullandığı ara\xe7larda y\xfcr\xfct\xfcl\xfcr ve kararın alındığı ana bağlantı verir.",points:["Kararları g\xf6revlere ve takip e-postalarına d\xf6n\xfcşt\xfcrmek","Her \xf6nerinin kaynağını g\xf6stermek","\xd6nemli her işi bir kişinin onaylaması"]}],note:"Talos, \xfczerinde \xe7alıştığımız bir konsept; bug\xfcn kullanılabilen bir \xfcr\xfcn değil.",cta:{title:"Toplantılarda alınan kararlar kayboluyor mu?",body:"Toplantıların takibi ekibiniz i\xe7in bir sorunsa, bug\xfcn nasıl y\xfcr\xfcd\xfcğ\xfcn\xfc dinlemek isteriz.",button:"Toplantı takibini konuşalım"}}],s=[{...n[0],kind:"Интернет-магазин бутика",tag:"Работающий сайт",hero:{title:"Характер вашего бутика — в телефоне покупателя.",lead:"Интернет-магазин, построенный вокруг одного бутика: сначала коллекции, быстрые покупки с телефона, а повседневное управление — в руках владельца.",media:t},sections:[{...n[0].sections[0],kicker:"Знакомство",title:"Он открывается как лукбук.",body:"Первыми посетителей встречают кампании и коллекции, поэтому магазин ощущается как сам бутик, а не как список товаров. Владелец меняет их в панели управления."},{...n[0].sections[1],kicker:"Выбор",title:"Найти свой размер — самое простое.",body:"Фильтры по размеру и цвету, таблица размеров у каждого товара, избранное на потом и поиск по всему каталогу — всё удобно и для большого пальца, и для мыши.",points:["Фильтры по размеру и цвету","Таблица размеров","Избранное","Поиск"]},{kicker:"За прилавком",title:"Магазином управляет владелец.",body:"Новинки, цены и остатки по каждому размеру, кампании на главной и коллекции — всё управляется из собственной панели бутика. Письма магазина уходят от имени бутика, а ответы приходят прямо владельцу. Новые товары могут приходить и черновиками от Oddkin Operator — чат-ассистента, который мы сделали для магазина.",media:{kind:"chips",items:["Главная","Коллекции","Категории","Товары","Остатки","Черновики","Заказы"]}}],cta:{title:"Хотите магазин, который ощущается как ваш бутик?",body:"Мы проектируем интернет-магазины под ваш бренд и ваш способ продаж — и поддерживаем их после запуска.",button:"Обсудить ваш магазин"}},{...n[1],kind:"Маркетплейс бутиков",tag:"Работающий сайт",hero:{title:"Независимые магазины. Один общий мир покупок.",lead:"AdaTrend собирает независимые бутики в одном месте. Каждый сохраняет своё имя и характер, а покупатели просматривают их все вместе.",media:r},sections:[{...n[1].sections[0],kicker:"Вместе",title:"Каждый бутик сохраняет свой характер.",body:"У каждого магазина своя страница, имя и стиль. Вместе они становятся одним каталогом, где покупатели видят их рядом."},{...n[1].sections[1],kicker:"01 \xb7 Покупатели",title:"Все бутики сразу.",body:"Единый каталог всех магазинов, у каждого товара видно, откуда он. Оформление заказа без регистрации, адрес доставки по геолокации телефона и турецкий или английский в одно касание."},{...n[1].sections[2],kicker:"02 \xb7 Продавцы",title:"Каждый магазин ведёт свой уголок.",body:"У каждого бутика своя страница и панель для товаров, размеров и остатков, заказов, профиля и места на карте."},{kicker:"03 \xb7 Оператор",title:"Порядок поддерживает команда платформы.",body:"Новые бутики появляются только после одобрения. Команда может назначить или передать управление магазином, зайти в панель любого бутика, чтобы помочь, и следит за общими категориями.",media:{kind:"chips",items:["Бутики","Категории","Ждут одобрения","Одобрить","Передать владение"]}}],cta:{title:"Объединяете независимых продавцов?",body:"Мы проектируем витрину, инструменты продавцов и управление платформой как единый маркетплейс.",button:"Обсудить маркетплейс"}},{...n[2],kind:"Ассистент магазина в чате",tag:"Работает",hero:{title:"Говорите со своим магазином. День идёт своим ходом.",lead:"Oddkin Operator позволяет владельцу магазина вносить ежедневные изменения прямо из чата в телефоне. Ничего не меняется, пока владелец не подтвердит.",media:{kind:"chat"}},sections:[{kicker:"Кто решает",title:"Владелец остаётся главным.",body:"Ассистент предлагает описание и выбирает категорию из вашего списка. Цифры он никогда не угадывает — цены, размеры и остатки задаёте вы.",points:["Каждое изменение ждёт вашего нажатия. Написать \xabда\xbb — не значит подтвердить.","Публикация, цены и остатки приходят карточкой с кнопками.","Снятый товар не удаляется, а архивируется — его можно вернуть."]},{kicker:"В чате",title:"Всё, что нужно за день.",body:"Работает в Telegram и подключается к каждому магазину отдельно. Первый магазин — Fashion Paradise.",media:{kind:"chips",items:["Товар по фото","Найти товар","Цена по размерам","Изменить остатки","Добавить категорию","Снять товар"]}}],note:"Фото товара взято из работающего магазина Fashion Paradise; переписка и карточка — иллюстрация.",cta:{title:"Ваша команда каждый день повторяет одни и те же задачи?",body:"Мы создаём ассистентов, которые берут на себя рутину и оставляют каждое важное решение человеку.",button:"Обсудить ассистента"}},{...n[3],kind:"Агент: от встречи к делу",tag:"Концепт",hero:{title:"Встреча заканчивается. Работа движется дальше.",lead:"Project Talos — наш концепт агента, который замечает решения, принятые на встрече, предлагает следующие шаги и выполняет их в ваших рабочих инструментах после одобрения человеком.",media:{kind:"flow"}},sections:[{...n[3].sections[0],kicker:"01 \xb7 На встрече",title:"Что-то решено.",body:"Большинство встреч заканчиваются решениями, которые живут только в памяти людей и разрозненных заметках. Talos слушает моменты, когда кто-то берёт на себя обязательство."},{...n[3].sections[1],kicker:"02 \xb7 После встречи",title:"Talos предлагает следующий шаг.",body:"Услышать что-то на встрече — не значит получить разрешение. Talos готовит черновик действия, показывает, откуда оно взялось, и ждёт решения человека."},{kicker:"03 \xb7 Одобрено",title:"И это происходит — на виду у команды.",body:"После одобрения действие выполняется в инструментах, которыми команда уже пользуется, со ссылкой на момент, когда было принято решение.",points:["Превращать решения в задачи и письма","Показывать источник каждого предложения","Всё важное одобряет человек"]}],note:"Talos — концепт, над которым мы работаем, а не готовый продукт.",cta:{title:"Решения со встреч теряются?",body:"Если доводить решения со встреч до дела — проблема для вашей команды, расскажите, как это устроено сейчас.",button:"Обсудить встречи и задачи"}}],l={en:n,tr:o,ru:s},d={en:{chat:{photo:"New stock, photographed on the shop floor.",bot:"A beige T-shirt with a praying-hands print. From your categories, Tops › T-shirt fits. What's the price, and how many of each size?",owner:"2000 \xb7 S 2, M 3, L 1",product:"Praying hands print T-shirt",price:"₺2,000 \xb7 Tops › T-shirt",priceOnly:"₺2,000",publish:"Publish",published:"Published. It's in the shop now."},flow:["Conversation","Decision","Proposed action","Approval","Done, visibly"],proposal:{label:"Proposed action",action:"Send the revised order to the second supplier",owner:"Owner",due:"Due",dueValue:"Friday",from:"From",fromValue:"Weekly operations, 14:32",approve:"Approve",edit:"Edit",later:"Not now"}},tr:{chat:{photo:"Yeni \xfcr\xfcn, mağazada fotoğraflandı.",bot:"Dua eden eller baskılı, bej bir tiş\xf6rt. Kategorilerinizden \xdcst Giyim › T-shirt uyuyor. Fiyatı nedir, her bedenden ka\xe7 adet var?",owner:"2000 \xb7 S 2, M 3, L 1",product:"Dua Eden Eller Baskılı T-Shirt",price:"₺2.000 \xb7 \xdcst Giyim › T-shirt",priceOnly:"₺2.000",publish:"Yayınla",published:"Yayınlandı. Şu an mağazada."},flow:["Konuşma","Karar","\xd6nerilen iş","Onay","G\xf6r\xfcn\xfcr sonu\xe7"],proposal:{label:"\xd6nerilen iş",action:"G\xfcncel siparişi ikinci tedarik\xe7iye g\xf6nder",owner:"Sorumlu",due:"Son tarih",dueValue:"Cuma",from:"Kaynak",fromValue:"Haftalık operasyon, 14:32",approve:"Onayla",edit:"D\xfczenle",later:"Şimdi değil"}},ru:{chat:{photo:"Новый товар, сфотографирован в магазине.",bot:"Бежевая футболка с принтом \xabмолящиеся руки\xbb. Из ваших категорий подходит \xabВерх › Футболки\xbb. Какая цена и сколько каждого размера?",owner:"2000 \xb7 S 2, M 3, L 1",product:"Футболка с принтом \xabруки\xbb",price:"₺2 000 \xb7 Верх › Футболки",priceOnly:"₺2 000",publish:"Опубликовать",published:"Опубликовано. Товар уже в магазине."},flow:["Разговор","Решение","Предложение","Одобрение","Готово, на виду"],proposal:{label:"Предлагаемое действие",action:"Отправить обновлённый заказ второму поставщику",owner:"Ответственный",due:"Срок",dueValue:"Пятница",from:"Источник",fromValue:"Еженедельная планёрка, 14:32",approve:"Одобрить",edit:"Изменить",later:"Не сейчас"}}}}}]);